def choose_move(observation):
    # Defensive extraction of key info
    my_pos = observation.get('agent', {}).get('position', [0,0])
    grid_size = observation.get('grid_size', [1,1])
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    allies = observation.get('allies', [])
    territory = observation.get('territory', [])

    # Helper function to compute Manhattan distance
    def distance(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # Identify nearest target based on available info
    target = None
    min_dist = float('inf')

    # Condition: resource_collection
    if resources:
        for res in resources:
            res_pos = res.get('position')
            if res_pos is None:
                continue
            dist = distance(my_pos, res_pos)
            if dist < min_dist:
                min_dist = dist
                target = res_pos

    # Condition: pursuit_evasion
    elif enemies:
        for enemy in enemies:
            enemy_pos = enemy.get('position')
            if enemy_pos is None:
                continue
            dist = distance(my_pos, enemy_pos)
            if dist < min_dist:
                min_dist = dist
                target = enemy_pos

    # Condition: territory_control
    elif territory:
        # move towards the closest unclaimed cell within larger radius
        unclaimed = []
        for cell in territory:
            cell_pos = cell.get('position')
            claim_status = cell.get('claimed', True)
            if not claim_status:
                unclaimed.append(cell_pos)
        if unclaimed:
            for pos in unclaimed:
                dist = distance(my_pos, pos)
                if dist < min_dist:
                    min_dist = dist
                    target = pos
        # else no specific target

    # If no target found, stay still
    if target is None:
        return [0, 0]

    # Determine move direction towards target
    dx = 0
    dy = 0
    if target[0] > my_pos[0]:
        dx = 1
    elif target[0] < my_pos[0]:
        dx = -1
    elif target[0] == my_pos[0]:
        dx = 0

    if target[1] > my_pos[1]:
        dy = 1
    elif target[1] < my_pos[1]:
        dy = -1
    elif target[1] == my_pos[1]:
        dy = 0

    # Clamp moves to -1, 0, or 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))

    return [dx, dy]
